package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

const version = "0.4.2"

type options struct {
	command *string
	file    string
	login   bool
	norc    bool
}

func main() {
	name := filepath.Base(os.Args[0])
	opts, errText, errCode := parseOptions(name, os.Args[1:])
	if errText != "" {
		fmt.Fprint(os.Stderr, errText)
		os.Exit(errCode)
	}

	if opts == nil {
		return
	}

	shell, err := newShell(os.Stdin, os.Stdout, os.Stderr)
	if err != nil {
		fmt.Fprintf(os.Stderr, "nsh: %v\n", err)
		os.Exit(1)
	}
	shell.login = opts.login
	shell.ensureStateFiles()

	if !opts.norc {
		if status := shell.loadRCFiles(); status != 0 {
			os.Exit(status)
		}
	}

	switch {
	case opts.command != nil:
		os.Exit(shell.executeString(*opts.command))
	case opts.file != "":
		content, err := os.ReadFile(opts.file)
		if err != nil {
			printFilePanic(opts.file, err)
			os.Exit(101)
		}
		os.Exit(shell.executeString(string(content)))
	default:
		if !isTTY(os.Stdout.Fd()) {
			fmt.Fprintln(os.Stderr, "nsh: warning: stdout is not a tty")
			os.Exit(0)
		}
		os.Exit(shell.repl())
	}
}

func parseOptions(name string, args []string) (*options, string, int) {
	var (
		opts        options
		positionals []string
	)

	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch arg {
		case "-h", "--help":
			fmt.Print(helpText(name))
			return nil, "", 0
		case "--version":
			fmt.Println(version)
			return nil, "", 0
		case "-l", "--login":
			opts.login = true
		case "--norc":
			opts.norc = true
		case "-c":
			if i+1 >= len(args) {
				return nil, formatCLIError(
					fmt.Sprintf("The argument '-c <command>' requires a value but none was supplied"),
					commandUsage(name, opts),
				), 1
			}
			cmd := args[i+1]
			opts.command = &cmd
			i++
		default:
			if strings.HasPrefix(arg, "-") {
				return nil, formatCLIError(
					fmt.Sprintf("Found argument '%s' which wasn't expected, or isn't valid in this context", arg),
					baseUsage(name),
				), 1
			}
			positionals = append(positionals, arg)
		}
	}

	if opts.command != nil {
		if len(positionals) > 1 {
			return nil, formatCLIError(
				fmt.Sprintf("Found argument '%s' which wasn't expected, or isn't valid in this context", positionals[1]),
				fmt.Sprintf("%s -c <command>", name),
			), 1
		}
		return &opts, "", 0
	}

	if len(positionals) > 1 {
		return nil, formatCLIError(
			fmt.Sprintf("Found argument '%s' which wasn't expected, or isn't valid in this context", positionals[1]),
			baseUsage(name),
		), 1
	}
	if len(positionals) == 1 {
		opts.file = positionals[0]
	}
	return &opts, "", 0
}

func helpText(name string) string {
	return fmt.Sprintf(`nsh 0.4.2
A command-line shell that focuses on performance and productivity.

USAGE:
    %s [FLAGS] [OPTIONS] [FILE]

FLAGS:
    -h, --help       Prints help information
    -l, --login      Behave like a login shell
        --norc       Don't load nshrc
        --version    Print the version

OPTIONS:
    -c <command>        The command to be executed

ARGS:
    <FILE>    The file to be executed
`, name)
}

func baseUsage(name string) string {
	return fmt.Sprintf("%s [FLAGS] [OPTIONS] [FILE]", name)
}

func commandUsage(name string, opts options) string {
	parts := []string{fmt.Sprintf("%s -c <command>", name)}
	if opts.login {
		parts = append(parts, "--login")
	}
	if opts.norc {
		parts = append(parts, "--norc")
	}
	return strings.Join(parts, " ")
}

func formatCLIError(message, usage string) string {
	return fmt.Sprintf("error: %s\n\nUSAGE:\n    %s\n\nFor more information try --help\n", message, usage)
}

func printFilePanic(path string, err error) {
	fmt.Fprintf(os.Stderr, "nsh: panicked at src/main.rs:114:34:\n")
	fmt.Fprintf(os.Stderr, "failed to open the file: %v\n\n", err)
	fmt.Fprintln(os.Stderr, "nsh: Something went wrong. Check out ~/.nsh.log and please file this bug on GitHub: https://github.com/nuta/nsh/issues")
}

