+		return "\x1b[0m"
+	case "bold":
+		return "\x1b[1m"
+	case "underline":
+		return "\x1b[4m"
+	case "red":
+		return "\x1b[31m"
+	case "blue":
+		return "\x1b[34m"
+	case "green":
+		return "\x1b[32m"
+	case "yellow":
+		return "\x1b[33m"
+	case "cyan":
+		return "\x1b[36m"
+	case "magenta":
+		return "\x1b[35m"
+	case "repo_status":
+		status, _ := gitRepoStatus(ctx.pwd)
+		return status
+	default:
+		return ""
+	}
