package main

import (
	"bufio"
	"bytes"
	"errors"
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
)

const (
	version       = "0.4.2"
	description   = "A command-line shell that focuses on performance and productivity."
	defaultPrompt = `\{cyan}\{bold}\{current_dir} $\{reset} `
	metaSentinel  = "__NSH_META__32f25e4b9d204e1f"
)

var (
	reDashNotFound = regexp.MustCompile(`^dash: \d+: (.+): not found$`)
	reDashIllegal  = regexp.MustCompile(`^dash: \d+: exit: Illegal number: .+$`)
)

type options struct {
	command    string
	file       string
	hasCommand bool
	hasFile    bool
	login      bool
	norc       bool
	version    bool
}

type parseResult struct {
	opts     options
	showHelp bool
	err      string
}

type shellMeta struct {
	status    int
	pwd       string
	prompt    string
	promptSet bool
}

type promptContext struct {
	home     string
	hostname string
	pwd      string
	remote   bool
}

func main() {
	prog := filepath.Base(os.Args[0])
	touchLog()

	parsed := parseArgs(os.Args[1:])
	if parsed.showHelp {
		fmt.Print(helpText(prog))
		return
	}
	if parsed.err != "" {
		printParseError(prog, parsed.opts, parsed.err)
		os.Exit(1)
	}
	if parsed.opts.version {
		fmt.Println(version)
		return
	}

	touchHistory()

	if !parsed.opts.hasCommand && !parsed.opts.hasFile {
		os.Exit(runNoCommand(parsed.opts))
	}

	if parsed.opts.hasFile {
		os.Exit(runFile(parsed.opts))
	}

	os.Exit(runCommand(parsed.opts))
}

func parseArgs(args []string) parseResult {
	if shouldShowHelp(args) {
		return parseResult{showHelp: true}
	}

	var opts options
	endOfOptions := false

	for i := 0; i < len(args); i++ {
		arg := args[i]
		if !endOfOptions {
			switch {
			case arg == "--":
				endOfOptions = true
				continue
			case arg == "--version":
				opts.version = true
				continue
			case arg == "--login":
				opts.login = true
				continue
			case arg == "--norc":
				opts.norc = true
				continue
			case strings.HasPrefix(arg, "--"):
				return parseResult{opts: opts, err: unexpectedArgument(arg)}
			case strings.HasPrefix(arg, "-") && arg != "-":
				for j := 1; j < len(arg); j++ {
					switch arg[j] {
					case 'l':
						opts.login = true
					case 'c':
						if opts.hasCommand {
							return parseResult{opts: opts, err: duplicateCommandFlag()}
						}
						if j+1 < len(arg) {
							opts.command = arg[j+1:]
							opts.hasCommand = true
							j = len(arg)
							continue
						}
						if i+1 >= len(args) {
							return parseResult{opts: opts, err: missingCommandValue()}
						}
						opts.command = args[i+1]
						opts.hasCommand = true
						i++
						j = len(arg)
					case 'h':
						return parseResult{showHelp: true}
					default:
						return parseResult{opts: opts, err: unexpectedArgument("-" + string(arg[j]))}
					}
				}
				continue
			}
		}

		if !opts.hasFile {
			opts.file = arg
			opts.hasFile = true
			continue
		}
		return parseResult{opts: opts, err: unexpectedArgument(arg)}
	}

	return parseResult{opts: opts}
}

func shouldShowHelp(args []string) bool {
	endOfOptions := false
	for _, arg := range args {
		if endOfOptions {
			break
		}
		switch {
		case arg == "--":
			endOfOptions = true
		case arg == "--help" || arg == "-h":
			return true
		case strings.HasPrefix(arg, "--"):
			continue
		case strings.HasPrefix(arg, "-") && arg != "-":
			for j := 1; j < len(arg); j++ {
				switch arg[j] {
				case 'h':
					return true
				case 'l':
				case 'c':
					j = len(arg)
				default:
					j = len(arg)
				}
			}
		}
	}
	return false
}

func helpText(prog string) string {
	return fmt.Sprintf(`nsh %s
%s

USAGE:
    %s [FLAGS] [OPTIONS] [FILE]

FLAGS:
    -h, --help       Prints help information
    -l, --login      Behave like a login shell
        --norc       Don't load nshrc
        --version    Print the version

OPTIONS:
    -c <command>        The command to be executed

ARGS:
    <FILE>    The file to be executed
`, version, description, prog)
}

func printParseError(prog string, opts options, message string) {
	fmt.Fprintf(os.Stderr, "error: %s\n\nUSAGE:\n    %s\n\nFor more information try --help\n", message, usageFor(prog, opts))
}

func usageFor(prog string, opts options) string {
	switch {
	case opts.hasCommand && opts.version:
		return fmt.Sprintf("%s -c <command> --version", prog)
	case opts.hasCommand:
		return fmt.Sprintf("%s -c <command>", prog)
	case opts.version:
		return fmt.Sprintf("%s --version", prog)
	default:
		return fmt.Sprintf("%s [FLAGS] [OPTIONS] [FILE]", prog)
	}
}

func unexpectedArgument(arg string) string {
	return fmt.Sprintf("Found argument '%s' which wasn't expected, or isn't valid in this context", arg)
}

func duplicateCommandFlag() string {
	return "The argument '-c <command>' was provided more than once, but cannot be used multiple times"
}

func missingCommandValue() string {
	return "The argument '-c <command>' requires a value but none was supplied"
}

func runNoCommand(opts options) int {
	script := preludeScript(opts) + "\n:\n"
	exitCode := runCapturedScript(script, "")
	if exitCode != 0 {
		return exitCode
	}
	if !isTTY(os.Stdout) {
		fmt.Fprintln(os.Stderr, "nsh: warning: stdout is not a tty")
	}
	if !isTTY(os.Stdout) {
		return 0
	}
	return runInteractive(opts)
}

func runCommand(opts options) int {
	return runCapturedScript(preludeScript(opts)+"\n"+opts.command+"\n", "")
}

func runFile(opts options) int {
	if err := ensureReadableFile(opts.file); err != nil {
		return panicLikeOpenFailure(opts.file, err)
	}
	script := preludeScript(opts) + "\n. \"$0\"\n"
	return runCapturedScript(script, opts.file)
}

func runCapturedScript(script, arg0 string) int {
	dashPath, err := exec.LookPath("dash")
	if err != nil {
		fmt.Fprintf(os.Stderr, "nsh: failed to find dash: %v\n", err)
		return 1
	}

	cmd := exec.Command(dashPath)
	cmd.Args = []string{arg0, "-c", script}
	cmd.Stdin = os.Stdin

	var stdout bytes.Buffer
	var stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	err = cmd.Run()
	exitCode := exitCodeFromErr(err)
	outText := stdout.String()
	errText, normalized := normalizeStderr(stderr.String())

	if outText != "" {
		fmt.Fprint(os.Stdout, outText)
	}
	if errText != "" {
		fmt.Fprint(os.Stderr, errText)
	}

	switch {
	case normalized.illegalExit:
		return 1
	case normalized.commandNotFound:
		return 1
	case normalized.syntaxError:
		return 255
	default:
		return exitCode
	}
}

type stderrInfo struct {
	commandNotFound bool
	illegalExit     bool
	syntaxError     bool
}

func normalizeStderr(input string) (string, stderrInfo) {
	var info stderrInfo
	if input == "" {
		return "", info
	}

	lines := splitKeepingDelimiter(input)
	var out strings.Builder
	for _, line := range lines {
		newline := strings.HasSuffix(line, "\n")
		text := strings.TrimSuffix(line, "\n")

		switch {
		case reDashIllegal.MatchString(text):
			info.illegalExit = true
			continue
		case strings.Contains(text, "Syntax error:"):
			info.syntaxError = true
			out.WriteString(text)
		case reDashNotFound.MatchString(text):
			info.commandNotFound = true
			matches := reDashNotFound.FindStringSubmatch(text)
			out.WriteString(fmt.Sprintf("nsh: command not found `%s'", matches[1]))
		default:
			out.WriteString(text)
		}

		if newline {
			out.WriteByte('\n')
		}
	}

	return out.String(), info
}

func splitKeepingDelimiter(input string) []string {
	if input == "" {
		return nil
	}
	parts := strings.SplitAfter(input, "\n")
	if parts[len(parts)-1] == "" {
		return parts[:len(parts)-1]
	}
	return parts
}

func runInteractive(opts options) int {
	dashPath, err := exec.LookPath("dash")
	if err != nil {
		fmt.Fprintf(os.Stderr, "nsh: failed to find dash: %v\n", err)
		return 1
	}

	preludePath, err := writeTempPrelude(preludeScript(opts))
	if err != nil {
		fmt.Fprintf(os.Stderr, "nsh: failed to initialize shell: %v\n", err)
		return 1
	}
	defer os.Remove(preludePath)

	cmd := exec.Command(dashPath)
	cmd.Args = []string{"", "-s"}

	stdinPipe, err := cmd.StdinPipe()
	if err != nil {
		fmt.Fprintf(os.Stderr, "nsh: failed to initialize shell: %v\n", err)
		return 1
	}

	reader, outputWriter, err := combinedPipe()
	if err != nil {
		fmt.Fprintf(os.Stderr, "nsh: failed to initialize shell: %v\n", err)
		return 1
	}
	cmd.Stdout = outputWriter
	cmd.Stderr = outputWriter

	if err := cmd.Start(); err != nil {
		fmt.Fprintf(os.Stderr, "nsh: failed to initialize shell: %v\n", err)
		return 1
	}
	_ = outputWriter.Close()

	if _, err := io.WriteString(stdinPipe, ". "+shellQuote(preludePath)+"\n"+metaQuery()); err != nil {
		return waitAndReturn(cmd)
	}
	meta, readErr := readUntilMeta(reader)
	if readErr != nil {
		return waitAndReturn(cmd)
	}

	stdinReader := bufio.NewReader(os.Stdin)
	ctx := newPromptContext()

	for {
		fmt.Fprint(os.Stdout, renderPrompt(meta, ctx))

		line, err := stdinReader.ReadString('\n')
		if errors.Is(err, io.EOF) {
			_ = stdinPipe.Close()
			return waitAndReturn(cmd)
		}
		if err != nil {
			_ = stdinPipe.Close()
			return waitAndReturn(cmd)
		}

		if _, err := io.WriteString(stdinPipe, line+metaQuery()); err != nil {
			return waitAndReturn(cmd)
		}

		nextMeta, readErr := readUntilMeta(reader)
		if readErr != nil {
			return waitAndReturn(cmd)
		}
		meta = nextMeta
	}
}

func renderPrompt(meta shellMeta, ctx promptContext) string {
	promptSpec := meta.prompt
	if !meta.promptSet {
		promptSpec = defaultPrompt
	}
	ctx.pwd = meta.pwd
	return renderPromptSpec(promptSpec, ctx)
}

func newPromptContext() promptContext {
	home, _ := resolveHome()
	hostname, _ := os.Hostname()
	return promptContext{
		home:     home,
		hostname: hostname,
		remote:   os.Getenv("SSH_CONNECTION") != "" || os.Getenv("SSH_CLIENT") != "" || os.Getenv("SSH_TTY") != "",
	}
}

func renderPromptSpec(spec string, ctx promptContext) string {
	var out strings.Builder
	for i := 0; i < len(spec); {
		switch {
		case strings.HasPrefix(spec[i:], `\n`):
			out.WriteByte('\n')
			i += 2
		case strings.HasPrefix(spec[i:], `\{`):
			end := strings.IndexByte(spec[i+2:], '}')
			if end == -1 {
				out.WriteByte(spec[i])
				i++
				continue
			}
			out.WriteString(promptTokenValue(spec[i+2:i+2+end], ctx))
			i += 3 + end
		case strings.HasPrefix(spec[i:], `\if{`):
			cond, next, ok := readBrace(spec, i+3)
			if !ok {
				out.WriteString(`\if`)
				i += 3
				continue
			}
			thenPart, next, ok := readBrace(spec, next)
			if !ok {
				out.WriteString(`\if`)
				i += 3
				continue
			}
			elsePart, next, ok := readBrace(spec, next)
			if !ok {
				out.WriteString(`\if`)
				i += 3
				continue
			}
			if promptCondition(cond, ctx) {
				out.WriteString(renderPromptSpec(thenPart, ctx))
			} else {
				out.WriteString(renderPromptSpec(elsePart, ctx))
			}
			i = next
		default:
			out.WriteByte(spec[i])
			i++
		}
	}
	return out.String()
}

func readBrace(spec string, start int) (string, int, bool) {
	if start >= len(spec) || spec[start] != '{' {
		return "", start, false
	}
	depth := 0
	for i := start; i < len(spec); i++ {
		switch spec[i] {
		case '{':
			depth++
		case '}':
			depth--
			if depth == 0 {
				return spec[start+1 : i], i + 1, true
			}
		}
	}
	return "", start, false
}

func promptCondition(name string, ctx promptContext) bool {
	switch name {
	case "in_remote":
		return ctx.remote
	case "in_repo":
		_, ok := gitRepoStatus(ctx.pwd)
		return ok
	default:
		return false
	}
}

func promptTokenValue(name string, ctx promptContext) string {
	switch name {
	case "username":
		if user := os.Getenv("USER"); user != "" {
			return user
		}
		return "unknown"
	case "hostname":
		return ctx.hostname
	case "current_dir":
		return displayDir(ctx.pwd, ctx.home)
	case "reset":
		return "\x1b[0m"
	case "bold":
		return "\x1b[1m"
	case "underline":
		return "\x1b[4m"
	case "red":
		return "\x1b[31m"
	case "blue":
		return "\x1b[34m"
	case "green":
		return "\x1b[32m"
	case "yellow":
		return "\x1b[33m"
	case "cyan":
		return "\x1b[36m"
	case "magenta":
		return "\x1b[35m"
	case "repo_status":
		status, _ := gitRepoStatus(ctx.pwd)
		return status
	default:
		return ""
	}
}

func displayDir(pwd, home string) string {
	if home == "" {
		return pwd
	}
	if pwd == home {
		return "~"
	}
	if strings.HasPrefix(pwd, home+"/") {
		return "~" + pwd[len(home):]
	}
	return pwd
}

func gitRepoStatus(dir string) (string, bool) {
	if dir == "" {
		return "", false
	}

	headCmd := exec.Command("git", "rev-parse", "--abbrev-ref", "HEAD")
	headCmd.Dir = dir
	headOut, err := headCmd.Output()
	if err != nil {
		return "", false
	}

	name := strings.TrimSpace(string(headOut))
	if name == "" {
		return "", false
	}

	statusCmd := exec.Command("git", "status", "--porcelain")
	statusCmd.Dir = dir
	statusOut, err := statusCmd.Output()
	if err == nil && len(bytes.TrimSpace(statusOut)) > 0 {
		name += "*"
	}

	return name, true
}

func preludeScript(opts options) string {
	var out strings.Builder
	out.WriteString("cd() {\n")
	out.WriteString("    case $# in\n")
	out.WriteString("        0) command cd; return $? ;;\n")
	out.WriteString("        1)\n")
	out.WriteString("            if command cd \"$1\" 2>/dev/null; then\n")
	out.WriteString("                return 0\n")
	out.WriteString("            fi\n")
	out.WriteString("            printf \"nsh: cd: No such file or directory (os error 2): `%s'\\n\" \"$1\" >&2\n")
	out.WriteString("            return 1\n")
	out.WriteString("            ;;\n")
	out.WriteString("        *) command cd \"$@\"; return $? ;;\n")
	out.WriteString("    esac\n")
	out.WriteString("}\n")

	if !opts.norc {
		for _, rcPath := range rcPaths() {
			out.WriteString("[ -f ")
			out.WriteString(shellQuote(rcPath))
			out.WriteString(" ] && . ")
			out.WriteString(shellQuote(rcPath))
			out.WriteByte('\n')
		}
	}

	return out.String()
}

func rcPaths() []string {
	home, ok := resolveHome()
	if !ok || home == "" {
		return nil
	}

	xdg := os.Getenv("XDG_CONFIG_HOME")
	if xdg == "" {
		xdg = filepath.Join(home, ".config")
	}

	return []string{
		filepath.Join(home, ".nshrc"),
		filepath.Join(xdg, "nsh", "nshrc"),
	}
}

func resolveHome() (string, bool) {
	if home := os.Getenv("HOME"); home != "" {
		return home, true
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return "", false
	}
	return home, true
}

func touchLog() {
	touchUserFile(".nsh.log")
}

func touchHistory() {
	touchUserFile(".nsh_history")
}

func touchUserFile(name string) {
	home, ok := resolveHome()
	if !ok || home == "" {
		return
	}
	path := filepath.Join(home, name)
	file, err := os.OpenFile(path, os.O_RDONLY|os.O_CREATE, 0o644)
	if err != nil {
		return
	}
	_ = file.Close()
}

func writeLogMessage(message string) {
	home, ok := resolveHome()
	if !ok || home == "" {
		return
	}
	path := filepath.Join(home, ".nsh.log")
	file, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_APPEND, 0o644)
	if err != nil {
		return
	}
	defer file.Close()
	_, _ = io.WriteString(file, message)
}

func ensureReadableFile(path string) error {
	file, err := os.Open(path)
	if err != nil {
