func readUntilMeta(reader *bufio.Reader) (shellMeta, error) {
	var meta shellMeta
	sentinel := []byte(metaSentinel + "\x1e")

	for {
		chunk, err := reader.ReadBytes('\n')
		if len(chunk) > 0 {
			index := bytes.Index(chunk, sentinel)
			if index >= 0 {
				if index > 0 {
					_, _ = os.Stdout.Write(chunk[:index])
				}
				line := strings.TrimSuffix(string(chunk[index+len(sentinel):]), "\n")
				parts := strings.SplitN(line, "\x1e", 4)
