					return meta, nil
				}
			}
			_, _ = os.Stdout.Write(chunk)
		}
		if err != nil {
			return meta, err
		}
	}
}

func waitAndReturn(cmd *exec.Cmd) int {
	err := cmd.Wait()
	return exitCodeFromErr(err)
}

