		case ' ', '\t', '\r':
			t.advance()
		case '\n':
			line, col := t.line, t.col
			t.advance()
			return token{typ: tokenSemi, line: line, col: col}
		case '#':
			t.skipComment()
		case ';':
			line, col := t.line, t.col
			t.advance()
			return token{typ: tokenSemi, line: line, col: col}
		case '&':
